VALUES ('e1ad60f8-a098-56d7-8e18-915fe89f75f8', 'valid-anagram', 'Valid Anagram', 'Easy', 'Arrays & Hashing', 'Given two strings `s` and `t`, return `true` if `t` is an 
anagram
